1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ecef;
16	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2328;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 48px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow: hidden;
33	    white-space: nowrap;
34	    text-overflow: ellipsis;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 12px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 24px;
44	    height: 64px;
45	    border: none;
46	    border-radius: 14px;
47	    background: #3a3f45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59f00; }
53	  button.op.active { background: #fff; color: #f59f00; }
54	  button.clear { background: #868e96; }
55	  button.wide { grid-column: span 2; }
56	</style>
57	</head>
58	<body>
59	<div class="calc">
60	  <div class="display" data-testid="calc-display" data-value="0">0</div>
61	  <div class="keys">
62	    <button class="clear wide" data-testid="key-clear">AC</button>
63	    <button class="op" data-testid="key-div" data-op="/">÷</button>
64	    <button class="op" data-testid="key-mul" data-op="*">×</button>
65	
66	    <button data-testid="key-7">7</button>
67	    <button data-testid="key-8">8</button>
68	    <button data-testid="key-9">9</button>
69	    <button class="op" data-testid="key-sub" data-op="-">−</button>
70	
71	    <button data-testid="key-4">4</button>
72	    <button data-testid="key-5">5</button>
73	    <button data-testid="key-6">6</button>
74	    <button class="op" data-testid="key-add" data-op="+">+</button>
75	
76	    <button data-testid="key-1">1</button>
77	    <button data-testid="key-2">2</button>
78	    <button data-testid="key-3">3</button>
79	    <button class="op" data-testid="key-equals">=</button>
80	
81	    <button class="wide" data-testid="key-0">0</button>
82	    <button data-testid="key-dot">.</button>
83	  </div>
84	</div>
85	<script>
86	  var display = document.querySelector('[data-testid="calc-display"]');
87	
88	  var state = {
89	    entry: '0',       // text of the number being shown/typed
90	    stored: null,     // left operand
91	    op: null,         // pending operator
92	    fresh: true,      // next digit starts a new entry
93	    error: false
94	  };
95	
96	  // [REQ-001]
97	  function compute(a, op, b) {
98	    switch (op) {
99	      case '+': return a + b;
100	      case '-': return a - b;
101	      case '*': return a * b;
102	      case '/': return a / b;
103	    }
104	    return b;
105	  }
106	
107	  // [REQ-001]
108	  function render() {
109	    display.textContent = state.error ? 'Error' : state.entry;
110	    display.setAttribute('data-value', state.error ? 'NaN' : String(Number(state.entry)));
111	    document.querySelectorAll('button[data-op]').forEach(function (b) {
112	      b.classList.toggle('active', state.fresh && state.op === b.getAttribute('data-op'));
113	    });
114	  }
115	
116	  // [REQ-001]
117	  function setResult(value) {
118	    if (!isFinite(value)) {
119	      state.error = true;
120	      state.entry = '0';
121	      state.stored = null;
122	      state.op = null;
123	    } else {
124	      state.entry = String(value);
125	    }
126	    state.fresh = true;
127	  }
128	
129	  // [REQ-001]
130	  function inputDigit(d) {
131	    if (state.error) clearAll();
132	    if (state.fresh) {
133	      state.entry = d;
134	      state.fresh = false;
135	    } else {
136	      state.entry = state.entry === '0' ? d : state.entry + d;
137	    }
138	  }
139	
140	  // [REQ-001]
141	  function inputDot() {
142	    if (state.error) clearAll();
143	    if (state.fresh) {
144	      state.entry = '0.';
145	      state.fresh = false;
146	    } else if (state.entry.indexOf('.') === -1) {
147	      state.entry += '.';
148	    }
149	  }
150	
151	  // [REQ-001]
152	  // [REQ-002] Immediate execution: an operator key first finishes the waiting
153	  // operation, strictly left to right, no precedence. 2 + 3 × 4 = is 20.
154	  function inputOperator(op) {
155	    if (state.error) return;
156	    if (state.op !== null && !state.fresh) {
157	      setResult(compute(state.stored, state.op, Number(state.entry)));
158	      if (state.error) return;
159	    }
160	    state.stored = Number(state.entry);
161	    state.op = op;
162	    state.fresh = true;
163	  }
164	
165	  // [REQ-001]
166	  function equals() {
167	    if (state.error || state.op === null) return;
168	    var result = compute(state.stored, state.op, Number(state.entry));
169	    state.stored = null;
170	    state.op = null;
171	    setResult(result);
172	  }
173	
174	  // [REQ-001]
175	  function clearAll() {
176	    state.entry = '0';
177	    state.stored = null;
178	    state.op = null;
179	    state.fresh = true;
180	    state.error = false;
181	  }
182	
183	  document.querySelector('.keys').addEventListener('click', function (e) {
184	    var btn = e.target.closest('button');
185	    if (!btn) return;
186	    var id = btn.getAttribute('data-testid');
187	    if (/^key-\d$/.test(id)) inputDigit(id.slice(4));
188	    else if (id === 'key-dot') inputDot();
189	    else if (id === 'key-equals') equals();
190	    else if (id === 'key-clear') clearAll();
191	    else if (btn.hasAttribute('data-op')) inputOperator(btn.getAttribute('data-op'));
192	    render();
193	  });
194	
195	  render();
196	</script>
197	</body>
198	</html>
