// [REQ-003] Presentation only: at most 10 significant digits, no trailing
// zeros, exponential when |v| >= 1e10 or < 1e-9. Never applied to stored values.
function formatNumber(v) {
  var r = Number(v.toPrecision(10));
  if (r === 0) return '0';
  var abs = Math.abs(r);
  if (abs >= 1e10 || abs < 1e-9) {
    return r.toExponential(9).replace(/\.?0+e/, 'e');
  }
  var e = Math.floor(Math.log10(abs));
  var s = r.toFixed(Math.max(0, 10 - e));
  if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
  return s;
}

